class Solution {long distance(int[] p){return (long)p[0]*p[0]+(long)p[1]*p[1];}public int[][] solve(int[][] points,int k){Comparator<int[]> best=(a,b)->{int d=Long.compare(distance(a),distance(b));return d!=0?d:a[0]!=b[0]?Integer.compare(a[0],b[0]):Integer.compare(a[1],b[1]);};PriorityQueue<int[]> q=new PriorityQueue<>(best.reversed());for(int[] p:points){q.offer(p);if(q.size()>k)q.poll();}int[][] out=q.toArray(new int[0][]);Arrays.sort(out,best);return out;}}